SELECT product_id, DATE_TRUNC('MONTH', last_restock) AS last_restock_month, CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END AS last_restock_cohort, MAX(quantity) AS max_quantity, ROUND(AVG(quantity), 2) AS avg_quantity FROM inventory GROUP BY product_id, DATE_TRUNC('MONTH', last_restock), CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END HAVING avg_quantity < 66 ORDER BY max_quantity;
